CREATE TABLE identity_roles (
    code VARCHAR(16) NOT NULL PRIMARY KEY,
    display_name VARCHAR(80) NOT NULL
) ENGINE=InnoDB;

CREATE TABLE identity_login_buckets (
    bucket_key CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL PRIMARY KEY,
    attempts INT NOT NULL,
    expires_at DATETIME(6) NOT NULL,
    INDEX ix_identity_login_expiry (expires_at)
) ENGINE=InnoDB;

ALTER TABLE rulesets ADD CONSTRAINT fk_ruleset_active_version
    FOREIGN KEY (project_id, id, active_version_id)
    REFERENCES rule_versions(project_id, ruleset_id, id);

ALTER TABLE project_resources ADD CONSTRAINT fk_res_current_revision
    FOREIGN KEY (project_id, id, current_revision_id)
    REFERENCES resource_revisions(project_id, resource_id, id);

ALTER TABLE test_cases ADD CONSTRAINT fk_tc_current_revision
    FOREIGN KEY (project_id, id, current_revision_id)
    REFERENCES test_case_revisions(project_id, test_case_id, id);

CREATE TABLE cycle_statuses (
    code VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,
    label_vi VARCHAR(50) NOT NULL
) ENGINE=InnoDB;

CREATE TABLE execution_results (
    code VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,
    label_vi VARCHAR(50) NOT NULL
) ENGINE=InnoDB;

CREATE TABLE work_item_policy_versions (
    code VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,
    name VARCHAR(100) NOT NULL,
    definition_json JSON NOT NULL
) ENGINE=InnoDB;

ALTER TABLE test_cycles ADD CONSTRAINT ck_cycle_activation CHECK (
    (status_code='DRAFT' AND activated_at IS NULL AND activated_by IS NULL)
    OR (status_code IN ('ACTIVE','CLOSED') AND activated_at IS NOT NULL AND activated_by IS NOT NULL)
);

ALTER TABLE execution_attempts ADD COLUMN file_work_session_id BIGINT NULL,
    ADD CONSTRAINT fk_attempt_file_session FOREIGN KEY(project_id,file_work_session_id,executor_membership_id) REFERENCES file_work_sessions(project_id,id,executor_membership_id),
    ADD INDEX ix_attempt_file_session(project_id,file_work_session_id,run_item_id,id);

ALTER TABLE qa_details
    ADD CONSTRAINT fk_qa_current_answer FOREIGN KEY(project_id,work_item_id,generation,current_answer_id) REFERENCES qa_answers(project_id,work_item_id,generation,id),
    ADD CONSTRAINT fk_qa_current_confirmation FOREIGN KEY(project_id,work_item_id,generation,current_answer_id,current_confirmation_id) REFERENCES qa_confirmations(project_id,work_item_id,generation,answer_id,id);

ALTER TABLE qa_details
    ADD CONSTRAINT fk_qa_group_exact
        FOREIGN KEY(group_id,project_id) REFERENCES file_work_groups(id,project_id);

ALTER TABLE file_work_groups
    ADD INDEX ix_fw_group_source (project_id,document_id,cycle_id,configuration_id),
    DROP INDEX uq_fw_group_source;

ALTER TABLE test_cases ADD owning_document_id BIGINT,
 ADD CONSTRAINT uq_case_document UNIQUE(project_id,owning_document_id,id),
 ADD CONSTRAINT fk_case_document FOREIGN KEY(project_id,owning_document_id) REFERENCES import_batches(project_id,id);

CREATE TABLE testing_migration_case_map (
 project_id BIGINT NOT NULL, feature_id BIGINT NOT NULL, document_id BIGINT NOT NULL,
 old_case_id BIGINT NOT NULL, old_revision_id BIGINT NOT NULL, new_case_id BIGINT NOT NULL, new_revision_id BIGINT NOT NULL,
 PRIMARY KEY(project_id,document_id,old_case_id), FOREIGN KEY(project_id,feature_id,document_id) REFERENCES import_batches(project_id,feature_id,id),
 FOREIGN KEY(project_id,new_case_id,new_revision_id) REFERENCES test_case_revisions(project_id,test_case_id,id)
) ENGINE=InnoDB;

CREATE TABLE testing_migration_exceptions (
 id BIGINT AUTO_INCREMENT PRIMARY KEY, project_id BIGINT NOT NULL, source_batch_id BIGINT, code VARCHAR(64) NOT NULL,
 details VARCHAR(1000) NOT NULL, created_at DATETIME(6) NOT NULL, FOREIGN KEY(project_id) REFERENCES projects(id)
) ENGINE=InnoDB;

CREATE TABLE work_item_feature_history (
 id BIGINT AUTO_INCREMENT PRIMARY KEY, project_id BIGINT NOT NULL, work_item_id BIGINT NOT NULL,
 event_type VARCHAR(64) NOT NULL, before_json JSON, after_json JSON, actor_user_id VARCHAR(36) NOT NULL, created_at DATETIME(6) NOT NULL,
 FOREIGN KEY(project_id,work_item_id) REFERENCES work_items(project_id,id), FOREIGN KEY(actor_user_id) REFERENCES identity_users(id),
 INDEX ix_feature_issue_history(project_id,work_item_id,id)
) ENGINE=InnoDB;
